import six
import struct
import tempfile
import zlib
from robot.api import logger

from ..protobuf.definitions import ManagedObjectsDefinitions
from ..exception import InfoModelIms2ReaderException

from .frame import FRAME_PREFIX, FrameType, CompressionType, ChangeType


class ObjectUpdate(object):

    change_type = ChangeType.UPDATING

    def __init__(self, dist_name, object_dump):
        self.dist_name = dist_name
        self.object_dump = object_dump


class ObjectRemove(object):

    change_type = ChangeType.REMOVING

    def __init__(self, dist_name):
        self.dist_name = dist_name


class OperationRequest(object):

    change_type = ChangeType.EXECUTION_REQUESTING

    def __init__(self, sender_sic_address, request_id, dist_name, object_dump):
        self.sender_sic_address = sender_sic_address
        self.request_id = request_id
        self.dist_name = dist_name
        self.object_dump = object_dump


class OperationStatus(object):

    change_type = ChangeType.EXECUTION_STATUS

    def __init__(self, sender_sic_address, request_id, dist_name, status):
        self.sender_sic_address = sender_sic_address
        self.request_id = request_id
        self.dist_name = dist_name
        self.status = status


class ChangeSet(object):

    def __init__(self):
        self.updated = {}
        self.removed = []

        self.appenders = {
            ObjectUpdate: self._append_update,
            ObjectRemove: self._append_remove,
            OperationRequest: self._ignore,
            OperationStatus: self._ignore,
        }

    def append(self, item):
        """Append item to item set."""
        self.appenders[type(item)](item)

    def _append_update(self, item):
        self.updated[item.dist_name] = item.object_dump

    def _append_remove(self, item):
        self.removed.append(item.dist_name)

    def _ignore(self, item):
        pass


class Ims2DataProvider(object):

    def __init__(self, input_path, listener):
        self.input_path = input_path
        self.input_file = None
        self.definitions = None
        self.listener = listener
        self.pos = 0

        self.frame_readers = {
            FrameType.CHANGESET: self._read_changeset,
            FrameType.RESET: self._read_reset,
            FrameType.META: self._read_meta,
            FrameType.NODE_DETECTION: self._read_node_detection,
        }
        self.change_readers = {
            ChangeType.UPDATING: self._read_update,
            ChangeType.REMOVING: self._read_remove,
            ChangeType.EXECUTION_REQUESTING_OLD: self._read_execution_request_old,
            ChangeType.EXECUTION_REQUESTING: self._read_execution_request,
            ChangeType.EXECUTION_STATUS: self._read_execution_status,
        }

    def run(self):
        """Read and parse IMS2 file content."""
        with open(self.input_path, "rb") as input_file:
            self.input_file = input_file
            self.current_input = input_file
            self._read_header()
            while self._read_frame():
                pass

    def _read_header(self):
        version, header_size = self._read_int(count=2)
        if header_size < 4:
            raise InfoModelIms2ReaderException("Header is too short")

        additional_info_size = self._read_int()
        if additional_info_size > header_size - 4:
            raise InfoModelIms2ReaderException("Additional Info is larger than Header")

        additional_info = self._read_bytes(additional_info_size)  # noqa: F841
        self._read_bytes(header_size - 4 - additional_info_size)

    def _read_frame(self):
        prefix = self._read_bytes(len(FRAME_PREFIX))
        if not prefix:
            return False
        if prefix != FRAME_PREFIX:
            raise InfoModelIms2ReaderException("Invalid frame prefix")

        frame_type, compression_type, frame_size = self._read_int(count=3)
        if frame_type not in self.frame_readers:
            raise InfoModelIms2ReaderException("Unexpected frame type: {}".format(frame_type))

        if compression_type == CompressionType.GZIP:
            self._read_compressed_frame_content(frame_type, frame_size)
        else:
            self._read_frame_content(frame_type, frame_size)

        return True

    def _read_compressed_frame_content(self, frame_type, frame_size):
        frame_payload = self._read_bytes(frame_size)
        unzipped = zlib.decompress(frame_payload, 16 + zlib.MAX_WBITS)

        self.current_input = tempfile.TemporaryFile()
        self.current_input.write(unzipped)
        self.current_input.seek(0)

        try:
            self._read_frame_content(frame_type, len(unzipped))
        finally:
            self.current_input.close()
            self.current_input = self.input_file

    def _read_frame_content(self, frame_type, frame_size):
        self.pos = 0
        while self.pos < frame_size:
            self.frame_readers[frame_type](frame_size)

    def _read_reset(self, frame_size):
        if frame_size != 8:
            raise InfoModelIms2ReaderException("Reset frame length is not 8")
        self.listener.on_reset(self._read_timestamp())

    def _read_meta(self, frame_size):
        self.definitions = ManagedObjectsDefinitions(self._read_bytes(frame_size))
        self.listener.on_definitions_change(self.definitions)

    def _read_node_detection(self, frame_size):
        self._read_bytes(frame_size)

    def _read_changeset(self, frame_size):
        timestamp = self._read_timestamp()
        number_of_changes = self._read_int()
        changeset = ChangeSet()
        for i in range(number_of_changes):
            change = self._read_change()
            if change is not None:
                changeset.append(change)

        self.listener.on_update(changeset.updated, timestamp)
        self.listener.on_remove(changeset.removed, timestamp)

    def _read_change(self):
        dist_name_len = self._read_short_int()
        dist_name = self._read_string(dist_name_len)
        change_type = self._read_byte()
        if change_type not in self.change_readers:
            raise Exception("Unexpected change type: {}".format(change_type))
        return self.change_readers[change_type](dist_name)

    def _read_update(self, dist_name):
        payload_size = self._read_int()
        protobuf_msg = self._read_bytes(payload_size)
        try:
            decoder = self.definitions.get_decoder(dist_name)
        except Exception as e:
            logger.warn("Cannot decode object: {}".format(dist_name))
            self.listener.on_missing_mo_definition(dist_name)
            raise e
        try:
            object_dump = decoder.decode(protobuf_msg)
        except Exception:
            logger.warn("Cannot decode object: {}".format(dist_name))
            logger.warn("Check the correctness of IMS format, e.g in Web Admin")
        else:
            return ObjectUpdate(dist_name, object_dump)
        finally:
            for err in decoder.errors:
                self.listener.on_wrong_parameter(dist_name, err.get("parameter", None), err.get("value", None),
                                                 err.get("error_msg", None))

    def _read_remove(self, dist_name):
        return ObjectRemove(dist_name)

    def _read_execution_request_old(self, dist_name):
        sender_sic_address = self._read_int()  # noqa: F841
        payload_size = self._read_int()
        self._read_bytes(payload_size)
        return None

    def _read_execution_request(self, dist_name):
        sender_sic_address = self._read_int()
        sender_name_size = self._read_short_int()
        sender_name = self._read_bytes(sender_name_size)  # noqa: F841
        request_id = self._read_int()
        payload_size = self._read_int()
        protobuf_msg = self._read_bytes(payload_size)

        decoder = self.definitions.get_decoder(dist_name)
        object_dump = decoder.decode(protobuf_msg)
        return OperationRequest(sender_sic_address, request_id, dist_name, object_dump)

    def _read_execution_status(self, dist_name):
        sender_sic_address = self._read_int()
        sender_name_size = self._read_short_int()
        sender_name = self._read_bytes(sender_name_size)  # noqa: F841
        request_id = self._read_int()
        status = self._read_int()
        return OperationStatus(sender_sic_address, request_id, dist_name, status)

    def _read_string(self, length):
        string = self._read_bytes(length)
        if six.PY3 and isinstance(string, bytes):
            string = string.decode("utf-8")
        return string

    def _read_bytes(self, n):
        self.pos += n
        return self.current_input.read(n)

    def _read_int(self, count=1):
        return self._read_data(">{}i".format(count))

    def _read_short_int(self):
        return self._read_data(">H")

    def _read_byte(self):
        return ord(self._read_data(">c"))

    def _read_timestamp(self):
        return self._read_data(">q")

    def _read_data(self, fmt):
        bytes = struct.calcsize(fmt)
        self.pos += bytes
        result = struct.unpack(fmt, self.current_input.read(bytes))
        if len(result) == 1:
            return result[0]
        return result
